/**
 * Bundled sample drawings so anyone (e.g. a jury) can see a critique without drawing.
 * Generated by `npm run samples`, which also prints the `mark` coordinates: where each
 * sample's deliberate beginner mistake sits in the 1500×1125 photo.
 */
export const SAMPLES = [
  {
    id: "stilllife",
    file: "sample-stilllife.jpg",
    title: "Still life study",
    alt: "Pencil still life of a sphere and a cup on a table, shaded with hatching and a cast shadow.",
    tip: {
      title: "Open up the bottom of the cup.",
      body: "It's further below your eye level than the rim, so its ellipse should be rounder — right now it's flatter.",
    },
    mark: { cx: 996, cy: 720, rx: 126, ry: 36, rot: -1 },
  },
  {
    id: "boxes",
    file: "sample-boxes.jpg",
    title: "Boxes in perspective",
    alt: "Pencil sketch of two boxes in two-point perspective with a horizon line and construction lines.",
    tip: {
      title: "Aim both edges at one vanishing point.",
      body: "The small box's bottom edge drifts low, so its right side seems to swell as it recedes. Send it to the same point as the top edge.",
    },
    mark: { cx: 1232, cy: 668, rx: 134, ry: 39, rot: -10 },
  },
  {
    id: "portrait",
    file: "sample-portrait.jpg",
    title: "Head construction",
    alt: "Pencil sketch of a head built with the Loomis method: a circle, jaw line and facial guidelines.",
    tip: {
      title: "Lower the eyes a touch.",
      body: "Eyes sit about halfway down the head. Here they're slightly high, which makes the lower face look stretched.",
    },
    mark: { cx: 748, cy: 498, rx: 161, ry: 45, rot: -1 },
  },
  {
    id: "landscape",
    file: "sample-landscape.jpg",
    title: "Landscape sketch",
    alt: "Pencil landscape with distant hills, a winding path and a tree in the foreground.",
    tip: {
      title: "Let the far hills fade.",
      body: "Distance makes shapes lighter and softer. The hills are hatched darker than the tree in front, so they jump forward.",
    },
    mark: { cx: 560, cy: 560, rx: 488, ry: 99, rot: -1 },
  },
] as const;

export type SampleId = (typeof SAMPLES)[number]["id"];

export function getSample(id: string) {
  return SAMPLES.find((s) => s.id === id) ?? null;
}
